import { useState, useEffect } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { ArrowRight, ChevronLeft, ChevronRight } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { siteConfig } from '@/config/site'

export function Hero() {
  const [currentSlide, setCurrentSlide] = useState(0)

  useEffect(() => {
    const timer = setInterval(() => {
      setCurrentSlide((prev) => (prev + 1) % siteConfig.heroCarousel.length)
    }, 6000)
    return () => clearInterval(timer)
  }, [])

  const nextSlide = () => setCurrentSlide((prev) => (prev + 1) % siteConfig.heroCarousel.length)
  const prevSlide = () => setCurrentSlide((prev) => (prev - 1 + siteConfig.heroCarousel.length) % siteConfig.heroCarousel.length)

  return (
    <section className="relative h-[90vh] min-h-[600px] w-full overflow-hidden bg-black text-white">
      <AnimatePresence mode="wait">
        <motion.div
          key={currentSlide}
          initial={{ opacity: 0, scale: 1.05 }}
          animate={{ opacity: 1, scale: 1 }}
          exit={{ opacity: 0 }}
          transition={{ duration: 0.8, ease: "easeInOut" }}
          className="absolute inset-0"
        >
          <div className="absolute inset-0 bg-black/60 z-10" />
          <img 
            src={siteConfig.heroCarousel[currentSlide].image} 
            alt={siteConfig.heroCarousel[currentSlide].title}
            className="w-full h-full object-cover object-center"
          />
        </motion.div>
      </AnimatePresence>

      <div className="relative z-20 h-full container mx-auto px-6 md:px-12 flex flex-col justify-center">
        <div className="max-w-4xl space-y-6">
          <motion.div
            key={`title-${currentSlide}`}
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.6, delay: 0.2 }}
          >
            <h1 className="text-5xl md:text-7xl lg:text-8xl font-bold tracking-tight leading-[1.1]">
              {siteConfig.heroCarousel[currentSlide].title}
            </h1>
          </motion.div>

          <motion.p
            key={`subtitle-${currentSlide}`}
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.6, delay: 0.4 }}
            className="text-xl md:text-2xl text-gray-300 max-w-2xl font-light"
          >
            {siteConfig.heroCarousel[currentSlide].subtitle}
          </motion.p>

          <motion.div
            key={`cta-${currentSlide}`}
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.6, delay: 0.6 }}
            className="pt-4"
          >
            <Button size="lg" className="bg-white text-black hover:bg-gray-200 rounded-none px-8 py-6 text-lg font-semibold uppercase tracking-wider">
              {siteConfig.heroCarousel[currentSlide].cta} <ArrowRight className="ml-2 w-5 h-5" />
            </Button>
          </motion.div>
        </div>
      </div>

      <div className="absolute bottom-10 right-10 z-30 flex gap-4">
        <button onClick={prevSlide} className="p-3 border border-white/20 hover:bg-white hover:text-black transition-colors" aria-label="Previous slide">
          <ChevronLeft className="w-6 h-6" />
        </button>
        <button onClick={nextSlide} className="p-3 border border-white/20 hover:bg-white hover:text-black transition-colors" aria-label="Next slide">
          <ChevronRight className="w-6 h-6" />
        </button>
      </div>

      <div className="absolute bottom-10 left-6 md:left-12 z-30 flex gap-2">
        {siteConfig.heroCarousel.map((_, idx) => (
          <button 
            key={idx} 
            onClick={() => setCurrentSlide(idx)}
            className={`h-1 transition-all duration-300 ${currentSlide === idx ? 'w-12 bg-white' : 'w-4 bg-white/30'}`}
            aria-label={`Go to slide ${idx + 1}`}
          />
        ))}
      </div>
    </section>
  )
}
